<script setup lang="ts">import { onMounted, ref } from 'vue'; import axios from 'axios'; import api from '../plugins/axios'; const productos=ref<any[]>([]); const error=ref(''); const nombre=ref(''); const categoria=ref('Tortas'); const descripcion=ref(''); async function cargar(){try{productos.value=(await api.get('/productos')).data}catch(e){error.value=axios.isAxiosError(e)?e.response?.data?.message??'No se pudieron cargar los productos.':'No se pudieron cargar los productos.'}} async function crear(){try{await api.post('/productos',{nombre:nombre.value,categoria:categoria.value,descripcion:descripcion.value});nombre.value='';descripcion.value='';await cargar()}catch(e){error.value=axios.isAxiosError(e)?e.response?.data?.message??'No se pudo crear el producto.':'No se pudo crear el producto.'}} async function pausar(producto:any){try{await api.patch(`/productos/${producto.idProducto}/${producto.pausado?'reactivar':'pausar'}`);await cargar()}catch(e){error.value=axios.isAxiosError(e)?e.response?.data?.message??'No se pudo actualizar el producto.':'No se pudo actualizar el producto.'}} onMounted(cargar)</script>
<template><section class="container py-5"><h1 class="h2 fw-bold mb-4">Productos y presentaciones</h1><div v-if="error" class="alert alert-danger">{{ error }}</div><div class="card border-0 shadow-sm mb-4"><div class="card-body"><h2 class="h5">Nuevo producto</h2><div class="row g-2"><div class="col-md-4"><input v-model="nombre" class="form-control" placeholder="Nombre" /></div><div class="col-md-3"><select v-model="categoria" class="form-select"><option>Masitas</option><option>Rollos</option><option>Empanadas</option><option>Pays</option><option>Cupcakes</option><option>Tortas</option></select></div><div class="col-md-3"><input v-model="descripcion" class="form-control" placeholder="Descripción" /></div><div class="col-md-2"><button class="btn btn-primary w-100" type="button" @click="crear">Crear</button></div></div></div></div><div class="row g-3"><div v-for="producto in productos" :key="producto.idProducto" class="col-md-6 col-xl-4"><div class="card border-0 shadow-sm h-100"><div class="card-body"><h2 class="h5">{{ producto.nombre }}</h2><p class="text-secondary">{{ producto.categoria }}</p><p>{{ producto.pausado ? 'Pausado' : 'Activo' }}</p><button class="btn btn-sm btn-outline-primary" type="button" @click="pausar(producto)">{{ producto.pausado ? 'Reactivar' : 'Pausar' }}</button></div></div></div></div></section></template>
